/** @typedef {Readonly<{id:string,pattern:string,timbre:string,volume:number}>} StyleOrnament */
/** @typedef {[string,string,number]} Colour */
/** Each row is a deliberately balanced arrangement, independent of tempo.
 * Tuples are pattern, timbre, volume; the four slots are bell, pluck, phrase, FX.
 * @param {Colour} bell @param {Colour} pluck @param {Colour} phrase @param {Colour} fx
 * @returns {ReadonlyArray<StyleOrnament>} */
function arrangement(bell, pluck, phrase, fx) {
  return Object.freeze([bell, pluck, phrase, fx].map(([pattern,timbre,volume], index) =>
    Object.freeze({id:['bell','pluck','phrase','fx'][index],pattern,timbre,volume})))
}
/** Short names describe gestures, never genre or tempo guesses. */
