const G = 'pluck-gaps', S = 'pluck-sync', X = 'pluck-sixteen', T = 'pluck-thirds', C = 'pluck-chords'
const U = 'pluck-trance', D = 'pluck-trance-drive'
const L = 'strings-lift', Q = 'strings-fourths', R = 'strings-cluster-rise', W = 'strings-cluster-rise-wave'
const E = 'strings-cluster-fall', V = 'strings-cluster-fall-wave', H = 'synth-rush', P = 'piano-wide'
const K = 'crash-one', N = 'reverse-four', Z = 'transition'
